"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";

export function Label({ className, ...props }: ComponentProps<"label">) {
  return (
    <label
      data-slot="label"
      className={cn(
        "inline-block max-w-full text-sm leading-5 font-medium [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import { GlideHighlight, type GlideBox } from "./glide-highlight";
import { Label } from "./label";
import { cn } from "./lib/cn";
import "./otp-input.css";

export function OtpInput({
  label = "One-time code",
  length = 6,
  value,
  defaultValue = "",
  onValueChange,
  status = "idle",
  message,
  disabled,
  name,
  className,
}: {
  label?: string;
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  status?: "idle" | "error" | "success";
  /** Replaces the status line, e.g. why a code was refused or “Checking the code…”. */
  message?: string;
  disabled?: boolean;
  name?: string;
  className?: string;
}) {
  const [local, setLocal] = useState(defaultValue);
  const [active, setActive] = useState(0);
  const [box, setBox] = useState<GlideBox | null>(null);
  const inputs = useRef<Array<HTMLInputElement | null>>([]);
  const shell = useRef<HTMLDivElement>(null);
  const current = (value ?? local).slice(0, length);
  const live = useRef(current);
  const digits = Array.from({ length }, (_, index) => current[index] ?? "");

  function commit(next: string) {
    const clipped = next.replace(/\D/g, "").slice(0, length);
    live.current = clipped;
    if (value == null) setLocal(clipped);
    onValueChange?.(clipped);
  }

  useLayoutEffect(() => {
    live.current = current;
    const root = shell.current;
    const field = inputs.current[active];
    if (!root || !field) return;
    const rootRect = root.getBoundingClientRect();
    const rect = field.getBoundingClientRect();
    setBox({
      active: true,
      left: rect.left - rootRect.left,
      top: rect.top - rootRect.top,
      width: rect.width,
      height: rect.height,
    });
  }, [active, current]);

  return (
    <div className={cn("grid gap-2", className)}>
      <Label>{label}</Label>
      <div ref={shell} data-slot="otp" data-invalid={status === "error" || undefined} data-success={status === "success" || undefined} className="relative grid w-fit max-w-full gap-2" style={{ gridTemplateColumns: `repeat(${length}, minmax(0, 2.75rem))` }}>
        <GlideHighlight box={box} />
        {digits.map((digit, index) => (
          <span key={index} className="grid min-w-0">
          <input
            ref={(node) => {
              inputs.current[index] = node;
            }}
            inputMode="numeric"
            autoComplete={index === 0 ? "one-time-code" : "off"}
            aria-label={`${label} digit ${index + 1}`}
            disabled={disabled}
            value={digit}
            maxLength={1}
            className="z-10 col-start-1 row-start-1 h-11 w-full min-w-0 rounded-control bg-[var(--field)] shadow-[var(--shadow-field)] transition-shadow hover:shadow-[var(--shadow-field-hover)] text-center text-sm font-medium text-transparent tabular-nums caret-transparent outline-none focus-visible:shadow-[var(--shadow-field-focus)]"
            onFocus={() => setActive(index)}
            onChange={(event) => {
              const text = event.currentTarget.value.replace(/\D/g, "");
              const valueNow = live.current;
              if (text.length > 1) {
                commit(`${valueNow.slice(0, index)}${text}`);
                const next = Math.min(length - 1, index + text.length);
                inputs.current[next]?.focus();
                return;
              }
              const nextValue = `${valueNow.slice(0, index)}${text}${valueNow.slice(index + 1)}`;
              commit(nextValue);
              if (text) inputs.current[Math.min(length - 1, index + 1)]?.focus();
            }}
            onKeyDown={(event) => {
              if (event.key === "Backspace" && !live.current[index]) {
                event.preventDefault();
                const previous = Math.max(0, index - 1);
                commit(`${live.current.slice(0, previous)}${live.current.slice(previous + 1)}`);
                inputs.current[previous]?.focus();
              } else if (event.key === "ArrowLeft") {
                inputs.current[Math.max(0, index - 1)]?.focus();
              } else if (event.key === "ArrowRight") {
                inputs.current[Math.min(length - 1, index + 1)]?.focus();
              }
            }}
            onPaste={(event) => {
              event.preventDefault();
              const text = event.clipboardData.getData("text").replace(/\D/g, "");
              commit(`${live.current.slice(0, index)}${text}`);
              inputs.current[Math.min(length - 1, index + text.length)]?.focus();
            }}
          />
          <span aria-hidden="true" data-slot="otp-digit" key={digit || "empty"} className="pointer-events-none z-20 col-start-1 row-start-1 grid place-items-center text-sm font-medium text-foreground">
            {digit}
          </span>
          </span>
        ))}
        </div>
      {name ? <input type="hidden" name={name} value={current} /> : null}
      <p role="status" className={cn("min-h-5 text-xs", status === "error" ? "text-destructive" : "text-muted-foreground")}>
        {message ?? (status === "error" ? "That code was not accepted." : status === "success" ? "Code accepted." : `${current.length} of ${length} digits.`)}
      </p>
    </div>
  );
}

/* glide-highlight.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="glide-highlight"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: var(--radius-surface);
    background: var(--muted);
    opacity: 0;
    transition:
      transform var(--duration-travel) var(--ease-showcase),
      width var(--duration-travel) var(--ease-showcase),
      height var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="glide-highlight"][data-active="true"] {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="glide-highlight"] {
      transition: none;
    }
    [data-slot="glide-highlight"] {
      transition:
        transform 400ms var(--ease-showcase),
        width 400ms var(--ease-showcase),
        height 400ms var(--ease-showcase),
        opacity 280ms var(--ease-out);
    }
  }
}

/* otp-input.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="otp"][data-invalid="true"] {
    animation: caliper-reject var(--duration-travel) var(--ease-out);
  }
  [data-slot="otp"] [data-slot="glide-highlight"] {
    border-radius: var(--radius-overlay);
    background: transparent;
    box-shadow: 0 0 0 2px var(--foreground);
  }
  [data-slot="otp-digit"]:not(:empty) {
    animation: caliper-digit-in var(--duration-travel) var(--ease-showcase);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="otp-digit"]:not(:empty) {
      animation: caliper-digit-in 400ms var(--ease-showcase);
    }
    [data-slot="otp"][data-invalid="true"] {
      animation: caliper-reject 400ms var(--ease-out);
    }
  }
}
